static inline S_MirRecord *s_mir_record_new(int64_t id, size_t fields) {
	if (fields > (SIZE_MAX - sizeof(S_MirRecord)) / sizeof(S_MirField)) s_panic("collection too large");
	S_MirRecord *r = calloc(1, sizeof(S_MirRecord) + fields * sizeof(S_MirField));
	if (!r) s_panic("out of memory");
	r->type_id = id; r->refs = 1; s_arc_audit_new(r, r->refs); s_arc_audit_watch(r, s_mir_record_arc_scan); r->length = fields; r->capacity = fields; return r;
}
static inline S_MirRecord *s_mir_record_retain(S_MirRecord *r) { if (r) { ++r->refs; s_arc_audit_retain(r, r->refs); } return r; }
static inline S_MirRecord *s_mir_record_reserve_owned(S_MirRecord *r, size_t need) {
	if (need <= r->capacity) return r;
	const size_t limit = (SIZE_MAX - sizeof(S_MirRecord)) / sizeof(S_MirField);
	if (need > limit) s_panic("collection too large");
	size_t capacity = r->capacity ? r->capacity : 4;
	while (capacity < need) capacity = capacity > limit / 2 ? limit : capacity * 2;
	uintptr_t previous = (uintptr_t)r;
	S_MirRecord *grown = realloc(r, sizeof(S_MirRecord) + capacity * sizeof(S_MirField));
	if (!grown) s_panic("out of memory");
	s_arc_audit_relocate(previous, grown); grown->capacity = capacity; return grown;
}
