static inline S_MirRecord *s_mir_array_append_owned(S_MirRecord *array, S_MirField owned) {
	if (array->length >= (SIZE_MAX - sizeof(S_MirRecord)) / sizeof(S_MirField)) s_panic("collection too large");
	array = s_mir_record_unique_owned_reserved(array, 1);
	array = s_mir_record_reserve_owned(array, array->length + 1);
	array->fields[array->length++] = owned;
	return array;
}

static inline S_MirRecord *s_mir_dict_insert_owned(S_MirRecord *r, S_MirField key, S_MirField value) {
	r = s_mir_record_unique_owned(r);
	r->fields[0].dict = s_dict_insert(r->fields[0].dict, &key, &value); return r;
}
